1	'use strict';
2	
3	// Agent sync: keep SQLite `agents` table in lockstep with ~/.claude/agents/*.md.
4	// - Chokidar watches the agents dir. add/change/unlink → upsert/remove in registry.
5	// - On every mutation, emits on the shared EventEmitter so SSE clients push live.
6	// - reseedFromDisk() is called on server boot to close any gap from downtime.
7	//
8	// SQLite writes go through org.upsertAgent (which calls db.saveRegistry),
9	// so we inherit the existing transactional semantics and don't duplicate SQL.
10	
11	const fs = require('fs');
12	const path = require('path');
13	const os = require('os');
14	const { EventEmitter } = require('events');
15	const chokidar = require('chokidar');
16	
17	const { parseAgent } = require('./cache');
18	const org = require('../org');
19	
20	const HOME = os.homedir();
21	const AGENTS_DIR = path.join(HOME, '.claude', 'agents');
22	
23	const events = new EventEmitter();
24	events.setMaxListeners(100);
25	
26	let watcher = null;
27	
28	function deriveAgentRecord(parsed) {
29	  if (!parsed) return null;
30	  const { filename, name, description, model, tools } = parsed;
31	  return {
32	    name: name || filename,
33	    description: description || '',
34	    model: model || 'sonnet',
35	    role: typeof tools === 'string' ? tools : Array.isArray(tools) ? tools.join(',') : '',
36	  };
37	}
38	
39	function isAgentFile(p) {
40	  if (!p) return false;
41	  if (!p.endsWith('.md')) return false;
42	  const dir = path.dirname(p);
43	  return path.resolve(dir) === path.resolve(AGENTS_DIR);
44	}
45	
46	function agentIdFromPath(p) {
47	  return path.basename(p, '.md');
48	}
49	
50	function upsertFromDisk(agentId) {
51	  const filePath = path.join(AGENTS_DIR, `${agentId}.md`);
52	  if (!fs.existsSync(filePath)) {
53	    return { ok: false, reason: 'missing' };
54	  }
55	  const parsed = parseAgent(filePath);
56	  if (!parsed) return { ok: false, reason: 'parse_failed' };
57	
58	  const derived = deriveAgentRecord(parsed);
59	  const existing = org.findAgent(agentId);
60	
61	  // Merge: live metadata from disk overrides; org structure (department/phase/
62	  // reportsTo/level/etc.) is preserved from the existing registry record.
63	  // New agents get sensible defaults so they still render in the org chart.
64	  // Status defaults to 'pending' (not 'probation') so HR sees the new arrival
65	  // needs triage — department/reportsTo/tier MUST be assigned before the agent
66	  // is promoted to active. The org chart layout treats `pending` agents with
67	  // no `reportsTo` as "Unassigned" (NOT as a top leader), so a missing field
68	  // can no longer pollute the leadership row.
69	  const patch = {
70	    ...derived,
71	    status: existing?.status || 'pending',
72	    department: existing?.department ?? 'unassigned',
73	    reportsTo: existing?.reportsTo ?? null,
74	    title: existing?.title ?? (parsed.description?.slice(0, 80) || 'Agent'),
75	    tier: existing?.tier ?? 'engineer',
76	    level: existing?.level ?? 1,
77	    hiredAt: existing?.hiredAt || new Date().toISOString(),
78	  };
79	
80	  const saved = org.upsertAgent(agentId, patch);
81	  events.emit('agent:upsert', { agentId, agent: saved });
82	  if (!existing) {
83	    console.warn(
84	      `[agentSync] New disk-only agent "${agentId}" seeded with defaults — assign department/reportsTo/tier in registry.json`
85	    );
86	  }
87	  return { ok: true, agent: saved, isNew: !existing };
88	}
89	
90	function markRemoved(agentId) {
91	  const existing = org.findAgent(agentId);
92	  if (!existing) return { ok: false, reason: 'not_in_registry' };
93	  // Preserve the record; mark retired so history + reportsTo edges stay intact.
94	  const saved = org.upsertAgent(agentId, {
95	    status: 'retired',
96	    retiredAt: new Date().toISOString(),
97	    retiredReason: 'file_removed_from_disk',
98	  });
99	  events.emit('agent:remove', { agentId, agent: saved });
100	  return { ok: true, agent: saved };
101	}
102	
103	function reseedFromDisk() {
104	  const summary = { scanned: 0, upserted: 0, removed: 0, errors: [] };
105	  if (!fs.existsSync(AGENTS_DIR)) {
106	    return summary;
107	  }
108	  const files = fs.readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md'));
109	  summary.scanned = files.length;
110	
111	  const diskIds = new Set();
112	  for (const f of files) {
113	    const id = f.replace(/\.md$/, '');
114	    diskIds.add(id);
115	    try {
116	      const r = upsertFromDisk(id);
117	      if (r.ok) summary.upserted += 1;
118	      else summary.errors.push({ id, reason: r.reason });
119	    } catch (err) {
120	      summary.errors.push({ id, reason: err.message });
121	    }
122	  }
123	
124	  // Retire any active agent whose file was deleted while the server was off.
125	  try {
126	    for (const record of org.listAgentRecords()) {
127	      if (record.status === 'retired') continue;
128	      if (!diskIds.has(record.id)) {
129	        markRemoved(record.id);
130	        summary.removed += 1;
131	      }
132	    }
133	  } catch (err) {
134	    summary.errors.push({ id: '<reconcile>', reason: err.message });
135	  }
136	
137	  return summary;
138	}
139	
140	function startWatcher() {
141	  if (watcher) return watcher;
142	  if (!fs.existsSync(AGENTS_DIR)) {
143	    console.warn(`[agentSync] agents dir missing: ${AGENTS_DIR} — watcher not started`);
144	    return null;
145	  }
146	
147	  // Gotchas we hit:
148	  //  1. `awaitWriteFinish` + `depth:0` silently drop all events on macOS.
149	  //  2. A dotfile regex like `/(^|[\/\\])\../` also matches `.claude` in the
150	  //     watch path's parent, so chokidar excludes the whole dir. Use a function
151	  //     that only ignores dotfiles at leaf level.
152	  watcher = chokidar.watch(AGENTS_DIR, {
153	    persistent: true,
154	    ignoreInitial: true,
155	    ignored: (p) => path.basename(p).startsWith('.'),
156	  });
157	
158	  // Per-file debounce — collapses a burst (create → chmod → rename) into one.
159	  const pending = new Map();
160	  const schedule = (id, fn) => {
161	    const existing = pending.get(id);
162	    if (existing) clearTimeout(existing);
163	    pending.set(id, setTimeout(() => {
164	      pending.delete(id);
165	      try { fn(); } catch (err) { console.warn(`[agentSync] handler ${id}: ${err.message}`); }
166	    }, 150));
167	  };
168	
169	  const handleAddChange = (p) => {
170	    if (!isAgentFile(p)) return;
171	    const id = agentIdFromPath(p);
172	    schedule(id, () => {
173	      const r = upsertFromDisk(id);
174	      if (r.ok) console.log(`[agentSync] ${r.isNew ? 'added' : 'updated'}: ${id}`);
175	    });
176	  };
177	
178	  const handleUnlink = (p) => {
179	    if (!isAgentFile(p)) return;
180	    const id = agentIdFromPath(p);
181	    schedule(id, () => {
182	      const r = markRemoved(id);
183	      if (r.ok) console.log(`[agentSync] retired: ${id}`);
184	    });
185	  };
186	
187	  watcher.on('add', handleAddChange);
188	  watcher.on('change', handleAddChange);
189	  watcher.on('unlink', handleUnlink);
190	  watcher.on('error', (err) => console.warn(`[agentSync] watcher error: ${err.message}`));
191	  watcher.on('ready', () => console.log(`[agentSync] watcher ready (${Object.keys(watcher.getWatched()).length} dirs)`));
192	  if (process.env.AGENT_SYNC_DEBUG) {
193	    watcher.on('all', (ev, p) => console.log(`[agentSync:raw] ${ev} ${p}`));
194	  }
195	
196	  console.log(`[agentSync] watching ${AGENTS_DIR}`);
197	  return watcher;
198	}
199	
200	function stopWatcher() {
201	  if (watcher) {
202	    watcher.close();
203	    watcher = null;
204	  }
205	}
206	
207	module.exports = {
208	  AGENTS_DIR,
209	  events,
210	  upsertFromDisk,
211	  markRemoved,
212	  reseedFromDisk,
213	  startWatcher,
214	  stopWatcher,
215	};

