  `);

  // Reimport tags + squad from registry.json
  const fs = require('fs');
  const path = require('path');
  const HOME = require('os').homedir();
  const regFile = path.join(HOME, '.claude', 'org', 'registry.json');
  if (fs.existsSync(regFile)) {
