    let task = null;
    try {
      task = tasks.createTask({
        agentId: agentName,
        source: 'orchestration',
        taskType: node.data?.taskType || 'workflow',
        title: node.data?.label || nodeId,
        prompt: node.data?.instructions || lastOutput,
        priority: node.data?.priority || 'p2',
