import { useEffect, useRef, type ReactNode } from 'react'
import { AlertTriangle, X, Loader2 } from 'lucide-react'

export interface ConfirmDialogProps {
  open: boolean
  onClose: () => void
  onConfirm: () => void | Promise<void>
  title: string
  message?: ReactNode
  confirmLabel?: string
  cancelLabel?: string
  danger?: boolean
  loading?: boolean
  // Slot for cascade checkbox or extra inputs.
  children?: ReactNode
}

// Reusable confirm dialog. Esc closes, Enter confirms.
// Pattern matches AssignTaskModal overlay (fixed inset, blur, rounded card).
export default function ConfirmDialog({
  open, onClose, onConfirm, title, message,
  confirmLabel = 'Confirm', cancelLabel = 'Cancel',
  danger = false, loading = false, children,
}: ConfirmDialogProps) {
  const confirmRef = useRef<HTMLButtonElement>(null)

  // Esc / Enter handlers + focus the confirm button on open
  useEffect(() => {
    if (!open) return
    const t = setTimeout(() => confirmRef.current?.focus(), 50)
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault()
        onClose()
      } else if (e.key === 'Enter' && !loading) {
        e.preventDefault()
        Promise.resolve(onConfirm()).catch(() => {})
      }
    }
    window.addEventListener('keydown', onKey)
    return () => {
      clearTimeout(t)
      window.removeEventListener('keydown', onKey)
    }
  }, [open, onClose, onConfirm, loading])

  if (!open) return null

  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 backdrop-blur-sm"
      onClick={(e) => { if (e.target === e.currentTarget && !loading) onClose() }}
    >
      <div className="w-full max-w-md mx-4 rounded-2xl bg-surface border border-border shadow-2xl">
        <div className="flex items-start justify-between gap-3 px-5 py-4 border-b border-border">
          <div className="flex items-start gap-3">
            {danger && (
              <div className="w-8 h-8 rounded-full bg-red-500/15 ring-1 ring-red-500/30 flex items-center justify-center shrink-0">
                <AlertTriangle className="w-4 h-4 text-red-400" />
              </div>
            )}
            <div>
              <h2 className="text-sm font-bold leading-tight">{title}</h2>
              {message && (
                <p className="text-xs text-text-muted mt-1 leading-relaxed">{message}</p>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            disabled={loading}
            className="p-1 rounded hover:bg-surface-2 text-text-muted shrink-0 disabled:opacity-50"
            aria-label="Close"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>

        {children && (
          <div className="px-5 py-3 border-b border-border bg-surface-2/40">
            {children}
          </div>
        )}

        <div className="flex items-center justify-end gap-2 px-5 py-3 bg-surface-2/30 rounded-b-2xl">
          <button
            onClick={onClose}
            disabled={loading}
            className="px-3 py-1.5 text-xs font-bold rounded-lg bg-surface border border-border text-text-muted hover:text-text disabled:opacity-50"
          >
            {cancelLabel}
          </button>
          <button
            ref={confirmRef}
            onClick={() => Promise.resolve(onConfirm()).catch(() => {})}
            disabled={loading}
            className={`px-4 py-1.5 text-xs font-bold rounded-lg text-white flex items-center gap-1.5 disabled:opacity-50 disabled:cursor-not-allowed ${
              danger ? 'bg-red-500 hover:bg-red-600' : 'bg-accent hover:bg-accent/90'
            }`}
          >
            {loading && <Loader2 className="w-3 h-3 animate-spin" />}
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  )
}

