                  type="button"
                  onClick={() => setColor(c)}
                  className={`w-7 h-7 rounded-lg border-2 transition-all ${color === c ? 'ring-2 ring-offset-2 ring-offset-surface ring-accent' : 'border-transparent hover:scale-110'}`}
