{sectionHeading('Squad')}
<div className="flex flex-wrap gap-1.5">
  {dynSquads.map(sq => {
    const active = currentSquad === sq.id
    return (
      <button
        key={sq.id}
        type="button"
        onClick={() => setForm(f => ({ ...f, squad: active ? null : sq.id }))}
