// Detect pod membership from agent id prefix. Files named `pod-a-frontend`,
// `pod-b-tester`, `pod-c-backend`, etc. auto-route to their pod's lead so a
// freshly-dropped specialist file lands in the right column on first sync.
// Returns { pod, podLead, department } or null when the id has no pod prefix.
//
// `pod-a-lead` / `pod-b-lead` / `pod-c-lead` themselves are NOT routed by this
// helper — those are the leads, they report up to the engineering VP (arya).
function detectPodFromId(agentId) {
  const m = /^pod-([a-z])-([a-z0-9-]+)$/i.exec(agentId);
  if (!m) return null;
  const podLetter = m[1].toLowerCase();
  const role = m[2].toLowerCase();
  const podKey = `pod-${podLetter}`;
  if (role === 'lead') {
    // The pod-lead reports to the engineering VP, not to itself.
    return { pod: podKey, podLead: 'arya', department: 'engineering' };
  }
  return { pod: podKey, podLead: `${podKey}-lead`, department: 'engineering' };
}

