// ── Render plan — Row 2 columns ───────────────────────────────────────────
//
// For most depts: 1 column = 1 dept (with internal sub-dept group headers).
// For very tall depts (e.g. Engineering with 14+ members across 6 sub-pods):
// expand each sub-dept into its OWN Row 2 column. Same VP card on Row 1
// anchors all the split columns. This stops Engineering from being a
// 1500px tall single column and turns its sub-pods into a real tree.
const SPLIT_THRESHOLD_MEMBERS = 8  // dept with > N members + 2+ sub-depts → split
const SPLIT_THRESHOLD_SUBDEPTS = 2

type DeptEntry = typeof departments[number]
type ColumnPlan =
  | { kind: 'dept'; dept: DeptEntry }
  | { kind: 'subdept'; dept: DeptEntry; group: SubDeptGroup }

const plan: ColumnPlan[] = []
for (const d of departments) {
  const groups = d.subDeptGroups || []
  const shouldSplit = groups.length >= SPLIT_THRESHOLD_SUBDEPTS && d.visibleCount >= SPLIT_THRESHOLD_MEMBERS
  if (shouldSplit) {
    for (const g of groups) {
      if (g.members.length === 0) continue
      plan.push({ kind: 'subdept', dept: d, group: g })
    }
    // Also include any orphans (members with no subDepartment) as a residual column
    const ungrouped = d.members.filter(m => {
      if (d.head && m.id === d.head.id) return false
      return !groups.some(g => g.members.some(gm => gm.id === m.id))
    })
    if (ungrouped.length > 0) {
      plan.push({
        kind: 'subdept',
        dept: d,
        group: { id: `${d.id}-other`, label: 'Other', description: '', pod: null, members: ungrouped },
      })
    }
  } else {
    plan.push({ kind: 'dept', dept: d })
  }
}

