// ── Position math ───────────────────────────────────────────────────────────
const deptCount = departments.length
const deptsRowWidth = deptCount * DEPT_WIDTH
  + Math.max(0, deptCount - 1) * DEPT_ROW_GAP
const canvasWidth = Math.max(deptsRowWidth, LEADER_WIDTH)

const rexY = 0
const deptHeadsY = LEADER_HEIGHT + DEPT_HEAD_ROW_GAP
const deptColsY = deptHeadsY + LEADER_HEIGHT + LEADER_DEPT_GAP

const deptsStartX = (canvasWidth - deptsRowWidth) / 2

const rfNodes: Node[] = []
const rfEdges: Edge[] = []

// Row 0 — Rex
if (rex) {
  const { emoji, cleanName } = extractEmoji(rex.name)
  rfNodes.push({
    id: rex.id,
    type: 'orgLeader',
    position: { x: (canvasWidth - LEADER_WIDTH) / 2, y: rexY },
    // Explicit width/height — MiniMap reads these directly to draw the
    // node rect. Without them MiniMap waits on DOM measurement and
    // can render zero-size nodes mid-fitView.
    width: LEADER_WIDTH,
    height: LEADER_HEIGHT,
    data: {
      id: rex.id,
      name: cleanName,
      emoji,
      title: rex.title,
      model: rex.model,
      tier: rex.tier,
      phaseColor: rex.departmentColor || rex.phaseColor,
      description: rex.description,
      dimmed: false,
      level: rex.level ?? null,
      levelTitle: rex.levelTitle ?? null,
      yearsOfExperience: rex.yearsOfExperience ?? null,
      status: rex.status,
      activeTaskCount: rex.activeTaskCount ?? 0,
      maxConcurrentTasks: rex.maxConcurrentTasks ?? 3,
      loadStatus: rex.loadStatus ?? 'free',
      successRate: rex.successRate ?? null,
    } satisfies LeaderNodeData,
  })
}

// Row 1 + Row 2 — dept heads (above) and dept columns (below).
departments.forEach((dept, i) => {
  const colX = deptsStartX + i * (DEPT_WIDTH + DEPT_ROW_GAP)
  // Members shown inside the column EXCLUDE the dept head (rendered as Row 1)
  const visibleMembers = dept.head ? dept.members.filter(m => m.id !== dept.head!.id) : dept.members
  const memberCount = visibleMembers.length
  // Sub-dept group headers add height — only count groups with ≥1 visible member
  const groupCount = (dept.subDeptGroups || []).length
  const groupHeadersHeight = groupCount > 0
    ? groupCount * (SUBDEPT_HEADER_HEIGHT + SUBDEPT_HEADER_GAP)
    : 0
  const colHeight = DEPT_HEADER_HEIGHT
    + DEPT_PADDING_Y * 2
    + memberCount * MEMBER_ROW_HEIGHT
    + Math.max(0, memberCount - 1) * MEMBER_ROW_GAP
    + groupHeadersHeight

  // Department head leader card on Row 1, centered above its column.
  let deptHeadCardId: string | null = null
  if (dept.head) {
    deptHeadCardId = dept.head.id
    const { emoji, cleanName } = extractEmoji(dept.head.name)
    const headX = colX + (DEPT_WIDTH - LEADER_WIDTH) / 2
    rfNodes.push({
      id: dept.head.id,
      type: 'orgLeader',
      position: { x: headX, y: deptHeadsY },
      width: LEADER_WIDTH,
      height: LEADER_HEIGHT,
      data: {
        id: dept.head.id,
        name: cleanName,
        emoji,
        title: dept.head.title,
        model: dept.head.model,
        tier: dept.head.tier,
        phaseColor: dept.head.departmentColor || dept.head.phaseColor,
        description: dept.head.description,
        dimmed: false,
        level: dept.head.level ?? null,
        levelTitle: dept.head.levelTitle ?? null,
        yearsOfExperience: dept.head.yearsOfExperience ?? null,
        status: dept.head.status,
        activeTaskCount: dept.head.activeTaskCount ?? 0,
        maxConcurrentTasks: dept.head.maxConcurrentTasks ?? 3,
        loadStatus: dept.head.loadStatus ?? 'free',
        successRate: dept.head.successRate ?? null,
      } satisfies LeaderNodeData,
    })

    // Edge: always trunk every Row 1 dept-head card from Rex.
    // Routing from a head's actual `reportsTo` (e.g. Vega → Quill) creates
    // ugly horizontal loops between adjacent Row 1 cards. The trunk-from-Rex
    // pattern keeps Row 1 visually clean; sub-manager relationships still
    // surface inside the dept column via the indented sub-tree.
    if (rex && dept.head.id !== rex.id) {
      rfEdges.push({
        id: `e-${rex.id}-${dept.head.id}`,
        source: rex.id,
        target: dept.head.id,
        type: 'step',
        // pathOptions is valid at runtime for step/smoothstep edges but the
        // base Edge type doesn't expose it — cast through the typed form.
        pathOptions: { offset: 24, borderRadius: 0 },
        style: { stroke: 'var(--color-text)', strokeWidth: 1.75, opacity: 0.7 },
      } as Edge)
    }
  }

  // Department column on Row 2.
  const deptNodeId = `dept-${dept.id}`
  rfNodes.push({
    id: deptNodeId,
    type: 'orgDept',
    position: { x: colX, y: deptColsY },
    width: DEPT_WIDTH,
    height: colHeight,
    data: {
      // Reuse phase* field names so OrgDepartmentNode renders unchanged.
      phase: dept.id,
      phaseLabel: dept.label,
      phaseColor: dept.color,
      members: visibleMembers,
      subDeptGroups: dept.subDeptGroups,
      width: DEPT_WIDTH,
      height: colHeight,
      dimmed: false,
    } satisfies DepartmentNodeData,
  })

  // Edge: dept head → its column. Always drawn so each dept-head card
  // visibly connects to its dept column. Headless columns (Unassigned)
  // anchor to Rex with a dashed line so they don't float orphaned.
  const colEdgeSource = deptHeadCardId || rex?.id
  if (colEdgeSource) {
    rfEdges.push({
      id: `e-${colEdgeSource}-${deptNodeId}`,
      source: colEdgeSource,
      target: deptNodeId,
      type: 'step',
      pathOptions: { offset: 12, borderRadius: 0 },
      style: {
        stroke: dept.color,
        strokeWidth: 2,
        opacity: deptHeadCardId ? 0.7 : 0.35,
        strokeDasharray: deptHeadCardId ? undefined : '4 4',
      },
    } as Edge)
  }
})

