const deptsStartX = (canvasWidth - deptsRowWidth) / 2
const colXFor = (i: number) => deptsStartX + i * (DEPT_WIDTH + DEPT_ROW_GAP)

// Pre-compute each dept's head card X (centered over its column span).
// Rex needs to sit at the centroid of ALL head positions, NOT the canvas
// center — when one dept (Engineering) spans 6 cols and others span 1,
// canvas-center is way off from where the VP cluster actually sits.
const deptHeadXMap = new Map<string, number>()
{
  const tmpSpans = new Map<string, { firstIdx: number; lastIdx: number }>()
  plan.forEach((entry, i) => {
    const cur = tmpSpans.get(entry.dept.id)
    if (cur) cur.lastIdx = i
    else tmpSpans.set(entry.dept.id, { firstIdx: i, lastIdx: i })
  })
  for (const [deptId, span] of tmpSpans) {
    const startX = colXFor(span.firstIdx)
    const endX = colXFor(span.lastIdx) + DEPT_WIDTH
    const headX = (startX + endX) / 2 - LEADER_WIDTH / 2
    deptHeadXMap.set(deptId, headX)
  }
}

const rfNodes: Node[] = []
const rfEdges: Edge[] = []

// Row 0 — Rex centered over the cluster of dept-head card positions.
if (rex) {
  const { emoji, cleanName } = extractEmoji(rex.name)
  const headXs = Array.from(deptHeadXMap.values())
  let rexX: number
  if (headXs.length > 0) {
    // Center Rex on the midpoint of (leftmost head, rightmost head + width)
