// ── Render plan — Row 2 columns ─────────────────────────────────────────────
// For most depts: 1 col = 1 dept. Splitting engineering into 6 sub-cols
// pushed canvas width to ~4100px which made fitView shrink cards to
// unreadable size on standard viewports. Disable split by default — keep
// sub-dept group headers inside the single tall column instead. Set
// SPLIT_THRESHOLD_MEMBERS to 999 to effectively disable; codepath kept for
// future viewport-aware activation.
const SPLIT_THRESHOLD_MEMBERS = 999
const SPLIT_THRESHOLD_SUBDEPTS = 999

type DeptEntry = typeof departments[number]
type ColumnPlan =
  | { kind: 'dept'; dept: DeptEntry; deptColor: string; label: string; members: MemberInfo[]; subDeptGroups?: SubDeptGroup[] }
  | { kind: 'subdept'; dept: DeptEntry; deptColor: string; label: string; members: MemberInfo[]; subDeptId: string }

const plan: ColumnPlan[] = []
for (const d of departments) {
  const groups = d.subDeptGroups || []
  const visibleHead = d.head?.id
  const nonHead = (xs: MemberInfo[]) => visibleHead ? xs.filter(m => m.id !== visibleHead) : xs
  const totalVisible = nonHead(d.members).length
  const shouldSplit = groups.length >= SPLIT_THRESHOLD_SUBDEPTS && totalVisible >= SPLIT_THRESHOLD_MEMBERS

  if (shouldSplit) {
    // Emit one column per sub-dept (skip empty after dropping head)
    for (const g of groups) {
      const memList = nonHead(g.members)
      if (memList.length === 0) continue
      plan.push({
        kind: 'subdept',
        dept: d,
        deptColor: d.color,
        label: g.label,
        members: memList,
        subDeptId: g.id,
      })
    }
    // Residual: dept members not assigned to any sub-dept
    const grouped = new Set<string>()
    for (const g of groups) for (const m of g.members) grouped.add(m.id)
    const ungrouped = nonHead(d.members).filter(m => !grouped.has(m.id))
    if (ungrouped.length > 0) {
      plan.push({
        kind: 'subdept',
        dept: d,
        deptColor: d.color,
        label: 'Other',
        members: ungrouped,
        subDeptId: `${d.id}-other`,
      })
    }
  } else {
    plan.push({
      kind: 'dept',
      dept: d,
      deptColor: d.color,
      label: d.label,
      members: nonHead(d.members),
      subDeptGroups: groups,
    })
  }
}

