// Row 1 + Row 2 — render the plan.
// Step 1: render every Row-2 column. Track dept → col-index span so the
// VP card can be centered over a multi-column span.
const deptColSpans = new Map<string, { dept: DeptEntry; firstIdx: number; lastIdx: number; nodeIds: string[] }>()

plan.forEach((entry, i) => {
  const colX = colXFor(i)
  const memberCount = entry.members.length
  const groupCount = entry.kind === 'dept' ? (entry.subDeptGroups || []).length : 0
  const groupHeadersHeight = groupCount > 0
    ? groupCount * (SUBDEPT_HEADER_HEIGHT + SUBDEPT_HEADER_GAP)
    : 0
  const colHeight = DEPT_HEADER_HEIGHT
    + DEPT_PADDING_Y * 2
    + memberCount * MEMBER_ROW_HEIGHT
    + Math.max(0, memberCount - 1) * MEMBER_ROW_GAP
    + groupHeadersHeight

  const nodeId = entry.kind === 'subdept'
    ? `dept-${entry.dept.id}-${entry.subDeptId}`
    : `dept-${entry.dept.id}`

  rfNodes.push({
    id: nodeId,
    type: 'orgDept',
    position: { x: colX, y: deptColsY },
    width: DEPT_WIDTH,
    height: colHeight,
    data: {
      phase: entry.dept.id,
      phaseLabel: entry.label,
      phaseColor: entry.deptColor,
      members: entry.members,
      // Only the dept-kind column shows internal sub-dept group headers;
      // when split, each sub-dept IS the column so headers are redundant.
      subDeptGroups: entry.kind === 'dept' ? entry.subDeptGroups : undefined,
      width: DEPT_WIDTH,
      height: colHeight,
      dimmed: false,
    } satisfies DepartmentNodeData,
  })

  // Track span for dept-head positioning
  const span = deptColSpans.get(entry.dept.id)
  if (span) {
    span.lastIdx = i
    span.nodeIds.push(nodeId)
  } else {
    deptColSpans.set(entry.dept.id, { dept: entry.dept, firstIdx: i, lastIdx: i, nodeIds: [nodeId] })
  }
})

// Step 2: render Row-1 dept-head card per dept (centered over its col span)
// + edges from Rex → head, and head → each col.
for (const span of deptColSpans.values()) {
  const dept = span.dept
  const head = dept.head

  if (head) {
    const { emoji, cleanName } = extractEmoji(head.name)
    // Center the head card over the dept's full column span.
    const spanStartX = colXFor(span.firstIdx)
    const spanEndX = colXFor(span.lastIdx) + DEPT_WIDTH
    const headX = (spanStartX + spanEndX) / 2 - LEADER_WIDTH / 2

    rfNodes.push({
      id: head.id,
      type: 'orgLeader',
      position: { x: headX, y: deptHeadsY },
      width: LEADER_WIDTH,
      height: LEADER_HEIGHT,
      data: {
        id: head.id,
        name: cleanName,
        emoji,
        title: head.title,
        model: head.model,
        tier: head.tier,
        phaseColor: head.departmentColor || head.phaseColor,
        description: head.description,
        dimmed: false,
        level: head.level ?? null,
        levelTitle: head.levelTitle ?? null,
        yearsOfExperience: head.yearsOfExperience ?? null,
        status: head.status,
        activeTaskCount: head.activeTaskCount ?? 0,
        maxConcurrentTasks: head.maxConcurrentTasks ?? 3,
        loadStatus: head.loadStatus ?? 'free',
