// Persistent drag positions — loaded once on mount + after any save/reset
// event. Applied as override on top of the auto-computed layout.
const [positionOverrides, setPositionOverrides] = useState<Record<string, { x: number; y: number }>>({})
useEffect(() => {
  let cancelled = false
  import('../lib/api').then(({ getOrgChartPositions }) =>
    getOrgChartPositions()
      .then(({ positions }) => {
        if (cancelled) return
        const out: Record<string, { x: number; y: number }> = {}
        for (const [nid, p] of Object.entries(positions)) out[nid] = { x: p.x, y: p.y }
        setPositionOverrides(out)
      })
      .catch(() => {/* non-critical — fall back to auto layout */}),
  )
  return () => { cancelled = true }
}, [])

