{/* Detail panel — rendered inside fullscreen container so it stays visible */}
{selectedNodeData && (
  <DetailPanel
    node={selectedNodeData}
    allNodes={data.nodes}
    onClose={() => onSelectNode(null)}
    onNavigate={onNavigateToNode}
    onOrgSaved={onOrgSaved}
    locked={!!positionOverrides[selectedNodeData.id]?.locked}
    onToggleLock={async (next) => {
      try {
        const { toggleOrgChartLock, saveOrgChartPositions } = await import('../lib/api')
        // If user locks a card with no saved position yet, persist its
        // current on-screen position first so the lock pins it where
        // it visibly sits, not at (0,0).
        const current = positionOverrides[selectedNodeData.id]
        if (next && !current) {
          const liveNode = nodes.find(n => n.id === selectedNodeData.id)
          if (liveNode) {
            await saveOrgChartPositions([{ nodeId: selectedNodeData.id, x: liveNode.position.x, y: liveNode.position.y }])
          }
        }
        await toggleOrgChartLock(selectedNodeData.id, next)
        await reloadPositions()
        toast('success', next ? 'Card locked' : 'Card unlocked')
      } catch (e: unknown) {
        toast('error', e instanceof Error ? e.message : 'Lock toggle failed')
      }
    }}
  />
)}

